export const SOURCE = {"src/index.js":"import { DrimeSmgr } from './storage/drime_smgr.js';\nimport { parseSQL } from './parser/parser.js';\nimport { planQuery } from './planner/planner.js';\nimport { Executor } from './executor/executor.js';\nimport { provisionDatabase } from './tenant/provision.js';\nimport { DRIME_BASE } from './core/constants.js';\nimport { WireBrain } from './protocol/wire_brain.js';\nimport { hashPassword, signToken, verifyToken, uid } from './auth.js';\nimport { SOURCE } from './source_bundle.js';\nimport HTML_DASHBOARD from './dashboard_html.js';\n\nconst K = { config:'config', keys:'keys', customers:'customers' };\nconst cors = { 'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,PUT,DELETE,OPTIONS','Access-Control-Allow-Headers':'Content-Type, Authorization','Content-Type':'application/json' };\nconst json = (o,s=200)=>new Response(JSON.stringify(o),{status:s,headers:cors});\nconst kvGet = async(kv,k)=>{try{return await kv.get(k,'json')}catch(e){return null}};\nconst kvPut = async(kv,k,v)=>{await kv.put(k,JSON.stringify(v))};\n\nasync function listFiles(apiKey){ try{ const r=await fetch(DRIME_BASE+'/drive/file-entries?workspaceId=0',{headers:{Authorization:'Bearer '+apiKey,Accept:'application/json'}}); if(!r.ok)return[]; const d=await r.json(); return d.data||[]; }catch(e){return[]} }\nasync function downloadRaw(apiKey,id){ try{ const h=btoa(String(id)); const r=await fetch(DRIME_BASE+'/file-entries/download/'+h,{headers:{Authorization:'Bearer '+apiKey}}); if(!r.ok)return null; return new Uint8Array(await r.arrayBuffer()); }catch(e){return null} }\nasync function deleteFile(apiKey,id){ for(const mk of [()=>fetch(DRIME_BASE+'/file-entries/'+id,{method:'DELETE',headers:{Authorization:'Bearer '+apiKey,Accept:'application/json'}}),()=>fetch(DRIME_BASE+'/file-entries/'+id+'?_method=DELETE',{method:'POST',headers:{Authorization:'Bearer '+apiKey,Accept:'application/json'}})]){ try{ const r=await mk(); if(r.ok||r.status===204)return true; }catch(e){} } return false; }\nasync function keyHealth(apiKey){ try{ const r=await fetch(DRIME_BASE+'/user/space-usage?workspaceId=0',{headers:{Authorization:'Bearer '+apiKey,Accept:'application/json'}}); if(r.ok){const s=await r.json();return{used:s.used,available:s.available,healthy:true};} }catch(e){} return{used:0,available:0,healthy:false}; }\n\nexport default {\n  async fetch(request, env) {\n    const kv = env.NE7_KV;\n    if (!kv) return json({error:'Bind KV namespace NE7_KV'},503);\n    const url = new URL(request.url);\n    const keys = await kvGet(kv,K.keys)||[];\n    const primary = keys.length?keys[0].key:null;\n\n    if (request.headers.get('Upgrade')==='websocket'){ const key=url.searchParams.get('key')||primary; const pair=new WebSocketPair(); const[client,server]=pair; server.accept(); const smgr=new DrimeSmgr(key,DRIME_BASE); const brain=new WireBrain({smgr,onSend:b=>server.send(b)}); server.addEventListener('message',e=>brain.feed(e.data)); return new Response(null,{status:101,webSocket:client}); }\n    if (request.method==='OPTIONS') return new Response(null,{headers:cors});\n    if (url.pathname==='/'&&request.method==='GET') return new Response(HTML_DASHBOARD,{headers:{'Content-Type':'text/html; charset=utf-8'}});\n\n    const headerKey=(request.headers.get('Authorization')||'').replace('Bearer ','');\n\n    if (url.pathname==='/api/setup'&&request.method==='POST'){ const b=await request.json(); const ex=await kvGet(kv,K.config); if(ex&&ex.setupDone)return json({error:'Already set up'},400); const h=await keyHealth(b.drimeKey); if(!h.healthy)return json({error:'Invalid Drime key'},400); const salt=uid(); await kvPut(kv,K.config,{setupDone:true,signSecret:uid()+uid(),admins:[{email:b.adminEmail.toLowerCase(),salt,passHash:await hashPassword(b.adminPassword,salt)}]}); await kvPut(kv,K.keys,[{id:uid(),nickname:b.keyNick||'Primary',key:b.drimeKey,capacityGB:20,status:'HEALTHY',createdAt:new Date().toISOString()}]); await kvPut(kv,K.customers,[]); return json({ok:true}); }\n\n    const config=await kvGet(kv,K.config)||{admins:[],signSecret:'x'};\n    if (url.pathname==='/api/login'&&request.method==='POST'){ const b=await request.json(); const customers=await kvGet(kv,K.customers)||[]; const email=(b.email||'').toLowerCase(); let role=null,tenantId=null,name=email; const admin=config.admins.find(a=>a.email===email); if(admin){if(await hashPassword(b.password,admin.salt)===admin.passHash)role='admin';} else{const c=customers.find(x=>x.email===email); if(c){if(await hashPassword(b.password,c.salt)===c.passHash){role='customer';tenantId=c.tenantId;name=c.name;}}} if(!role)return json({error:'Invalid credentials'},401); const token=await signToken({email,role,tenantId,name,exp:Date.now()+7*864e5},config.signSecret); return json({token,role,name}); }\n\n    const auth=await verifyToken(headerKey,config.signSecret);\n    const isAuthed=auth&&auth.exp>Date.now();\n    const isAdmin=isAuthed&&auth.role==='admin';\n    if(url.pathname==='/api/me')return isAuthed?json({email:auth.email,role:auth.role,name:auth.name,tenantId:auth.tenantId}):json({error:'unauthed'},401);\n\n    // ═══ ADMIN ═══\n    if (url.pathname.startsWith('/api/admin/')){\n      if(!isAdmin)return json({error:'Admin only'},403);\n      if(url.pathname==='/api/admin/keys'&&request.method==='GET')return json(keys.map(k=>({id:k.id,nickname:k.nickname,key:k.key.slice(0,6)+'••••••••'+k.key.slice(-4),capacityGB:k.capacityGB,status:k.status||'UNKNOWN'})));\n      if(url.pathname==='/api/admin/keys'&&request.method==='POST'){const b=await request.json(); const h=await keyHealth(b.key); keys.push({id:uid(),nickname:b.nickname,key:b.key,capacityGB:b.capacityGB||20,status:h.healthy?'HEALTHY':'DOWN',createdAt:new Date().toISOString()}); await kvPut(kv,K.keys,keys); return json({ok:true,healthy:h.healthy});}\n      if(url.pathname==='/api/admin/keys'&&request.method==='PUT'){const b=await request.json(); const k=keys.find(x=>x.id===b.id); if(k){if(b.nickname)k.nickname=b.nickname; await kvPut(kv,K.keys,keys);} return json({ok:true});}\n      let m=url.pathname.match(/^\\/api\\/admin\\/keys\\/([^/]+)\\/reveal$/); if(m){const k=keys.find(x=>x.id===m[1]);return json({key:k?k.key:null});}\n      m=url.pathname.match(/^\\/api\\/admin\\/keys\\/([^/]+)$/); if(m&&request.method==='DELETE'){await kvPut(kv,K.keys,keys.filter(k=>k.id!==m[1]));return json({ok:true});}\n      if(url.pathname==='/api/admin/admins'&&request.method==='GET')return json(config.admins.map(a=>a.email));\n      if(url.pathname==='/api/admin/admins'&&request.method==='POST'){const b=await request.json();const salt=uid();config.admins.push({email:b.email.toLowerCase(),salt,passHash:await hashPassword(b.password||'admin123',salt)});await kvPut(kv,K.config,config);return json({ok:true});}\n      m=url.pathname.match(/^\\/api\\/admin\\/admins\\/(.+)$/); if(m&&request.method==='DELETE'){config.admins=config.admins.filter(a=>a.email!==decodeURIComponent(m[1]));await kvPut(kv,K.config,config);return json({ok:true});}\n      if(url.pathname==='/api/admin/customers'&&request.method==='GET'){const cs=await kvGet(kv,K.customers)||[];return json(cs.map(c=>({id:c.id,email:c.email,name:c.name,tenantId:c.tenantId,createdAt:c.createdAt})));}\n      if(url.pathname==='/api/admin/customers'&&request.method==='POST'){const b=await request.json();const cs=await kvGet(kv,K.customers)||[];const tenant=b.name.replace(/[^a-z0-9_]/gi,'_').toLowerCase();const salt=uid();cs.push({id:uid(),email:b.email.toLowerCase(),name:b.name,tenantId:tenant,salt,passHash:await hashPassword(b.password,salt),createdAt:new Date().toISOString()});await kvPut(kv,K.customers,cs);\n        // ⚡ Failover-aware: pick healthiest key (most balance)\n        let best=null,bestFree=-1; for(const k of keys){const h=await keyHealth(k.key); if(h.healthy){const free=h.available; if(free>bestFree){bestFree=free;best=k;}}}\n        if(!best)return json({error:'No healthy Drime key available'},503);\n        const prov=await provisionDatabase(best.key,tenant,tenant,new DrimeSmgr(best.key,DRIME_BASE),best.id); return json({ok:true,dsn:prov.dsn,key:best.nickname});}\n      m=url.pathname.match(/^\\/api\\/admin\\/customers\\/([^/]+)$/); if(m&&request.method==='DELETE'){await kvPut(kv,K.customers,(await kvGet(kv,K.customers)||[]).filter(c=>c.id!==m[1]));return json({ok:true});}\n      if(url.pathname==='/api/admin/storage'){let gT=0,gU=0;const rows=[];for(const k of keys){const h=await keyHealth(k.key);const used=+(h.used/1e9).toFixed(2);gT+=k.capacityGB;gU+=used;k.status=h.healthy?'HEALTHY':'DOWN';rows.push({id:k.id,nickname:k.nickname,capacityGB:k.capacityGB,usedGB:used,balanceGB:+(k.capacityGB-used).toFixed(2),status:k.status});}await kvPut(kv,K.keys,keys);return json({rows,grandTotalGB:gT,grandUsedGB:+gU.toFixed(2),grandBalanceGB:+(gT-gU).toFixed(2)});}\n      // 🧨 DANGER ZONE RESET (wipe DBs + customers, KEEP admins + keys)\n      if(url.pathname==='/api/admin/reset'&&request.method==='POST'){let deleted=0;for(const k of keys){const files=await listFiles(k.key);for(const f of files){if(f.name.startsWith('t_')||f.name.startsWith('ne7_index')){if(await deleteFile(k.key,f.id))deleted++;}}}await kvPut(kv,K.customers,[]);return json({ok:true,deleted});}\n      // 📘 NE7 PANEL SOURCE\n      if(url.pathname==='/api/admin/source')return json(SOURCE);\n      return json({error:'not found'},404);\n    }\n\n    // ═══ DATA ═══\n    if(!isAuthed)return json({error:'unauthed'},401);\n    const tenant=isAdmin?(url.searchParams.get('tenant')||auth.tenantId||'default'):auth.tenantId;\n\n    if(url.pathname==='/api/databases'){const dbs=[];const seen={};for(const k of keys){const files=await listFiles(k.key);for(const mf of files.filter(f=>f.name.includes('__manifest.json'))){const tid=mf.name.replace('__manifest.json','').replace(/^t_/,'');if(!isAdmin&&tid!==auth.tenantId)continue;if(seen[tid])continue;seen[tid]=true;const raw=await downloadRaw(k.key,mf.id);if(raw){try{const mm=JSON.parse(new TextDecoder().decode(raw));dbs.push({id:mm.tenant,name:mm.name||mm.tenant,tables:Object.keys(mm.tables||{}).length,key:k.nickname});}catch(e){}}}}return json(dbs);}\n\n    if(url.pathname==='/api/query'&&request.method==='POST'){const b=await request.json();const sql=b.sql;\n      // ⚡ FAILOVER: tenant's key first, then others\n      let order=[...keys];for(const k of keys){const files=await listFiles(k.key);if(files.some(f=>f.name==='t_'+tenant+'__manifest.json')){order=[k,...keys.filter(x=>x.id!==k.id)];break;}}\n      let lastErr;for(const k of order){try{const smgr=new DrimeSmgr(k.key,DRIME_BASE);const ast=parseSQL(sql);const plan=planQuery(ast);const exec=new Executor(smgr,tenant);const res=await exec.execute(plan);return json({...res,ms:5,message:res.command,key:k.nickname});}catch(e){lastErr=e;}}\n      return json({error:lastErr?lastErr.message:'All keys failed',message:lastErr?lastErr.message:'error'},400);}\n\n    return json({engine:'NE7-SQL',status:'Online'});\n  }\n};\n","src/parser/parser.js":"import { tokenize } from './lexer.js';\n\nclass Parser {\n  constructor(tokens) { this.tokens = tokens; this.pos = 0; }\n  peek() { return this.tokens[this.pos]; }\n  consume(type) { \n    const t = this.peek(); \n    if (!t || (type && t.type !== type)) throw new Error(`Expected ${type} but got ${t?.type}`); \n    this.pos++; return t; \n  }\n  match(type) { return this.peek()?.type === type; }\n\n  parse() {\n    const t = this.peek();\n    if (!t) throw new Error('Empty query');\n    if (t.type === 'SELECT') return this.parseSelect();\n    if (t.type === 'INSERT') return this.parseInsert();\n    if (t.type === 'CREATE') return this.parseCreate();\n    if (t.type === 'DROP') return this.parseDrop();\n    throw new Error('Unsupported statement: ' + t.type);\n  }\n\n  parseSelect() {\n    this.consume('SELECT');\n    const cols = this.match('OP') && this.peek().value === '*' ? (this.consume('OP'), ['*']) : this.parseColList();\n    this.consume('FROM');\n    const table = this.consume('IDENT').value;\n    let where = null;\n    if (this.match('WHERE')) { this.consume('WHERE'); where = this.parseExpr(); }\n    return { type: 'SELECT', columns: cols, table, where };\n  }\n\n  parseInsert() {\n    this.consume('INSERT'); this.consume('INTO');\n    const table = this.consume('IDENT').value;\n    const cols = this.match('OP') && this.peek().value === '(' ? this.parseParenList() : [];\n    this.consume('VALUES');\n    const values = this.parseParenList();\n    return { type: 'INSERT', table, columns: cols, values };\n  }\n\n  parseCreate() {\n    this.consume('CREATE'); this.consume('TABLE');\n    const table = this.consume('IDENT').value;\n    this.consume('OP'); // (\n    const cols = [];\n    while (!this.match('OP') || this.peek().value !== ')') {\n      const name = this.consume('IDENT').value;\n      const dtype = this.consume('IDENT').value;\n      cols.push({ name, type: dtype });\n      if (this.match('OP') && this.peek().value === ',') this.consume('OP');\n    }\n    this.consume('OP'); // )\n    return { type: 'CREATE_TABLE', table, columns: cols };\n  }\n\n  parseDrop() {\n    this.consume('DROP'); this.consume('TABLE');\n    const table = this.consume('IDENT').value;\n    return { type: 'DROP_TABLE', table };\n  }\n\n  parseColList() {\n    const cols = [this.consume('IDENT').value];\n    while (this.match('OP') && this.peek().value === ',') { this.consume('OP'); cols.push(this.consume('IDENT').value); }\n    return cols;\n  }\n\n  parseParenList() {\n    this.consume('OP'); // (\n    const items = [];\n    while (!this.match('OP') || this.peek().value !== ')') {\n      const t = this.peek();\n      if (t.type === 'STRING' || t.type === 'NUMBER') { \n        items.push({ type: 'LITERAL', value: t.value }); \n        this.consume(); // 🛡️ FIXED: Only consume once for literals\n      } else { \n        items.push({ type: 'COLUMN', name: this.consume('IDENT').value }); \n      }\n      if (this.match('OP') && this.peek().value === ',') this.consume('OP');\n    }\n    this.consume('OP'); // )\n    return items;\n  }\n\n  parseExpr() {\n    let left = this.parsePrimary();\n    while (this.match('OP') || this.match('AND') || this.match('OR')) {\n      const op = this.consume().value;\n      const right = this.parsePrimary();\n      left = { type: 'BINOP', op, left, right };\n    }\n    return left;\n  }\n\n  parsePrimary() {\n    const t = this.peek();\n    if (t.type === 'STRING' || t.type === 'NUMBER') { this.consume(); return { type: 'LITERAL', value: t.value }; }\n    if (t.type === 'IDENT') { this.consume(); return { type: 'COLUMN', name: t.value }; }\n    throw new Error('Unexpected token in expression: ' + t.type);\n  }\n}\n\nexport function parseSQL(sql) {\n  const tokens = tokenize(sql);\n  return new Parser(tokens).parse();\n}\n","src/parser/lexer.js":"export class Token {\n  constructor(type, value) { this.type = type; this.value = value; }\n}\n\nexport function tokenize(sql) {\n  const tokens = [];\n  let i = 0;\n  const len = sql.length;\n  \n  while (i < len) {\n    let c = sql[i];\n    \n    // Skip whitespace\n    if (/\\s/.test(c)) { i++; continue; }\n    \n    // String literals\n    if (c === \"'\") {\n      i++; let val = '';\n      while (i < len && sql[i] !== \"'\") {\n        if (sql[i] === \"'\" && sql[i+1] === \"'\") { val += \"'\"; i += 2; } \n        else { val += sql[i]; i++; }\n      }\n      i++; tokens.push(new Token('STRING', val));\n      continue;\n    }\n    \n    // Numbers\n    if (/[0-9]/.test(c)) {\n      let val = '';\n      while (i < len && /[0-9.]/.test(sql[i])) { val += sql[i]; i++; }\n      tokens.push(new Token('NUMBER', parseFloat(val)));\n      continue;\n    }\n    \n    // Identifiers and Keywords\n    if (/[a-zA-Z_]/.test(c)) {\n      let val = '';\n      while (i < len && /[a-zA-Z0-9_]/.test(sql[i])) { val += sql[i]; i++; }\n      const upper = val.toUpperCase();\n      const kws = ['SELECT','FROM','WHERE','INSERT','INTO','VALUES','UPDATE','SET','DELETE','CREATE','TABLE','DROP','AND','OR'];\n      tokens.push(new Token(kws.includes(upper) ? upper : 'IDENT', val));\n      continue;\n    }\n    \n    // Operators & Punctuation\n    if (/[(),=*<>!]/.test(c)) {\n      let op = c;\n      if (i+1 < len && (c === '<' && sql[i+1] === '=' || c === '>' && sql[i+1] === '=' || c === '!' && sql[i+1] === '=')) {\n        op += sql[i+1]; i++;\n      }\n      i++; tokens.push(new Token('OP', op));\n      continue;\n    }\n    \n    i++; // Skip unknown\n  }\n  return tokens;\n}\n","src/planner/planner.js":"export function planQuery(ast) {\n  if (ast.type === 'SELECT') {\n    if (ast.where && ast.where.type === 'BINOP' && ast.where.op === '=') {\n      return { \n        type: 'IndexScan', \n        table: ast.table, \n        filter: ast.where, \n        columns: ast.columns, \n        cost: 50,\n        routing: 'INLINE'\n      };\n    }\n    return { \n      type: 'SeqScan', \n      table: ast.table, \n      columns: ast.columns, \n      cost: 1000,\n      routing: 'ASYNC'\n    };\n  }\n  \n  if (ast.type === 'INSERT') {\n    // 🛡️ Pass columns and values through to Executor\n    return { type: 'Insert', table: ast.table, columns: ast.columns, values: ast.values, cost: 10, routing: 'INLINE' };\n  }\n  \n  if (ast.type === 'CREATE_TABLE' || ast.type === 'DROP_TABLE') {\n    // 🛡️ Pass columns through to Executor for DDL\n    return { type: 'DDL', action: ast.type, table: ast.table, columns: ast.columns, cost: 5, routing: 'INLINE' };\n  }\n\n  return { type: 'Unknown', cost: 9999, routing: 'ASYNC' };\n}\n","src/executor/executor.js":"import { loadManifest, saveManifest } from '../storage/manifest.js';\nimport { randomId } from '../core/utils.js';\n\nexport class Executor {\n  constructor(smgr, tenantId) {\n    this.smgr = smgr;\n    this.tenantId = tenantId;\n  }\n\n  async execute(plan) {\n    const manifest = await loadManifest(this.smgr, this.tenantId);\n    if (!manifest) throw new Error('Tenant not found');\n\n    // ═══ DDL EXECUTION ═══\n    if (plan.type === 'DDL') {\n      if (plan.action === 'CREATE_TABLE') {\n        manifest.tables[plan.table] = { columns: plan.columns, segments: [], wal: [] };\n        await saveManifest(this.smgr, this.tenantId, manifest, manifest.version);\n        return { command: 'CREATE TABLE', rowCount: 0 };\n      }\n      if (plan.action === 'DROP_TABLE') {\n        delete manifest.tables[plan.table];\n        await saveManifest(this.smgr, this.tenantId, manifest, manifest.version);\n        return { command: 'DROP TABLE', rowCount: 0 };\n      }\n    }\n\n    // ═══ INSERT EXECUTION (Append to WAL) ═══\n    if (plan.type === 'Insert') {\n      const tableMeta = manifest.tables[plan.table];\n      if (!tableMeta) throw new Error(`Table ${plan.table} not found`);\n      \n      const row = {};\n      const cols = tableMeta.columns.map(c => c.name);\n      plan.values.forEach((v, i) => { row[cols[i]] = v.value; });\n\n      // Get or create active WAL segment ID\n      const walId = tableMeta.wal[0] || randomId();\n      if (!tableMeta.wal.includes(walId)) tableMeta.wal.push(walId);\n      \n      const walKey = `t_${this.tenantId}/wal_${walId}.json`;\n      const existing = await this.smgr.get(walKey);\n      const rows = existing ? JSON.parse(new TextDecoder().decode(existing)) : [];\n      rows.push(row);\n      \n      await this.smgr.put(walKey, new TextEncoder().encode(JSON.stringify(rows)));\n      await saveManifest(this.smgr, this.tenantId, manifest, manifest.version);\n      \n      return { command: 'INSERT', rowCount: 1 };\n    }\n\n    // ═══ SELECT EXECUTION (Scan WAL) ═══\n    if (plan.type === 'IndexScan' || plan.type === 'SeqScan') {\n      const tableMeta = manifest.tables[plan.table];\n      if (!tableMeta) throw new Error(`Table ${plan.table} not found`);\n      \n      const rows = [];\n      for (const walId of tableMeta.wal) {\n        const walKey = `t_${this.tenantId}/wal_${walId}.json`;\n        const data = await this.smgr.get(walKey);\n        if (data) rows.push(...JSON.parse(new TextDecoder().decode(data)));\n      }\n      \n      // Apply WHERE filter (IndexScan)\n      if (plan.type === 'IndexScan' && plan.filter) {\n        const { op, left, right } = plan.filter;\n        const colName = left.name;\n        const filterVal = right.value;\n        return {\n          command: 'SELECT',\n          rows: rows.filter(r => r[colName] == filterVal),\n          columns: tableMeta.columns\n        };\n      }\n      \n      return { command: 'SELECT', rows, columns: tableMeta.columns };\n    }\n\n    throw new Error('Unsupported plan: ' + plan.type);\n  }\n}\n","src/storage/drime_smgr.js":"export class DrimeSmgr {\n  constructor(apiKey, base) {\n    this.apiKey = apiKey;\n    this.base = base;\n    this.index = new Map();\n    this.indexLoaded = false;\n    this.cache = new Map(); \n  }\n\n  safeKey(key) { return key.replace(/\\//g, '__'); }\n\n  getApiHeaders() {\n    return { 'Authorization': `Bearer ${this.apiKey}`, 'Accept': 'application/json' };\n  }\n\n  getDownloadHeaders() {\n    return { 'Authorization': `Bearer ${this.apiKey}` };\n  }\n\n  async loadIndex() {\n    if (this.indexLoaded) return;\n    try {\n      const listR = await fetch(`${this.base}/drive/file-entries?workspaceId=0`, { headers: this.getApiHeaders() });\n      if (listR.ok) {\n        const data = await listR.json();\n        // Sort to get the newest index file\n        const files = data.data.sort((a, b) => b.id - a.id);\n        const indexFile = files.find(f => f.name.startsWith('ne7_index'));\n        \n        if (indexFile) {\n          // 🛡️ MASTER FIX: Base64 encode the ID and use /file-entries/download/\n          const hash = btoa(String(indexFile.id));\n          const dl = await fetch(`${this.base}/file-entries/download/${hash}`, { headers: this.getDownloadHeaders() });\n          \n          if (dl.ok) {\n            const text = await dl.text();\n            if (text.trim().startsWith('{')) {\n              this.index = new Map(Object.entries(JSON.parse(text)));\n              this.indexLoaded = true;\n              return;\n            }\n          }\n        }\n      }\n    } catch(e) {}\n    \n    // Fallback: Rebuild from file list\n    try {\n      const listR = await fetch(`${this.base}/drive/file-entries?workspaceId=0`, { headers: this.getApiHeaders() });\n      if (listR.ok) {\n        const data = await listR.json();\n        for (const file of data.data) if (!file.name.startsWith('ne7_index')) this.index.set(file.name, file.id);\n      }\n    } catch(e) {}\n    this.indexLoaded = true;\n  }\n\n  async saveIndex() {\n    const data = new TextEncoder().encode(JSON.stringify(Object.fromEntries(this.index)));\n    const fd = new FormData();\n    fd.append('file', new Blob([data]), `ne7_index_${Date.now()}.json`);\n    fd.append('parentId', ''); fd.append('workspaceId', '0');\n    const r = await fetch(`${this.base}/uploads`, { method: 'POST', headers: this.getApiHeaders(), body: fd });\n    if (r.ok) console.log('✅ Index saved to Drime');\n  }\n\n  async get(key) {\n    const sKey = this.safeKey(key);\n    if (this.cache.has(sKey)) return this.cache.get(sKey);\n    \n    await this.loadIndex();\n    const fileId = this.index.get(sKey);\n    if (!fileId) return null;\n\n    try {\n      // 🛡️ MASTER FIX: Base64 encode the ID and use /file-entries/download/\n      const hash = btoa(String(fileId));\n      const r = await fetch(`${this.base}/file-entries/download/${hash}`, { headers: this.getDownloadHeaders() });\n      \n      if (!r.ok) return null;\n      const data = new Uint8Array(await r.arrayBuffer());\n      \n      this.cache.set(sKey, data);\n      return data;\n    } catch (e) { return null; }\n  }\n\n  async put(key, data) {\n    await this.loadIndex();\n    const sKey = this.safeKey(key);\n    this.cache.set(sKey, data);\n    \n    const fd = new FormData();\n    fd.append('file', new Blob([data]), sKey);\n    fd.append('parentId', ''); fd.append('workspaceId', '0');\n    \n    const r = await fetch(`${this.base}/uploads`, { method: 'POST', headers: this.getApiHeaders(), body: fd });\n    if (!r.ok) throw new Error(`Upload failed: ${r.status}`);\n    const res = await r.json();\n    \n    this.index.set(sKey, res.fileEntry.id);\n    await this.saveIndex();\n    return true;\n  }\n}\n","src/storage/manifest.js":"export function defaultManifest(tenantId, dbName) {\n  return {\n    version: 0,\n    tenant: tenantId,\n    name: dbName,\n    tables: {},\n    wal: [],\n    segments: [],\n    indexes: []\n  };\n}\n\nexport async function loadManifest(smgr, tenantId) {\n  const b = await smgr.get(`t_${tenantId}/manifest.json`);\n  if (!b) return null;\n  const text = new TextDecoder().decode(b);\n  // 🛡️ MASTER FIX: If Drime returns an HTML error page instead of JSON, treat it as missing.\n  if (!text.trim().startsWith('{')) return null; \n  return JSON.parse(text);\n}\n\nexport async function saveManifest(smgr, tenantId, manifest, expectedVersion) {\n  const cur = await loadManifest(smgr, tenantId);\n  if (cur && cur.version !== expectedVersion) {\n    throw new Error('MANIFEST_CONFLICT: Concurrent writer detected');\n  }\n  manifest.version = expectedVersion + 1;\n  const data = new TextEncoder().encode(JSON.stringify(manifest));\n  await smgr.put(`t_${tenantId}/manifest.json`, data);\n  return manifest;\n}\n","src/protocol/wire_brain.js":"import { parseSQL } from '../parser/parser.js';\nimport { planQuery } from '../planner/planner.js';\nimport { Executor } from '../executor/executor.js';\n\nexport class WireBrain {\n  constructor({ smgr, onSend, defaultTenant }) {\n    this.smgr = smgr;\n    this.onSend = onSend;\n    this.tenant = defaultTenant || 'phase_c_test';\n    this.buf = Buffer.alloc(0);\n    this.handshake = false;\n  }\n\n  send(b){ this.onSend(b); }\n\n  feed(chunk){\n    this.buf = Buffer.concat([this.buf, Buffer.from(chunk)]);\n    while (this.buf.length >= 4) {\n      if (!this.handshake) {\n        const len = this.buf.readInt32BE(0);\n        if (this.buf.length < len) break;\n        const code = this.buf.readInt32BE(4);\n        if (len === 8 && code === 80877103) { this.send(Buffer.from('N')); this.buf = this.buf.slice(8); continue; }\n        if (code === 196608) { this.parseStartup(this.buf.slice(8, len)); this.sendStartupReply(); this.handshake = true; this.buf = this.buf.slice(len); continue; }\n        this.buf = this.buf.slice(len); continue;\n      }\n      if (this.buf.length < 5) break;\n      const type = this.buf[0];\n      const mlen = this.buf.readInt32BE(1);\n      const total = 1 + mlen;\n      if (this.buf.length < total) break;\n      const payload = this.buf.slice(5, total);\n      this.buf = this.buf.slice(total);\n      this.handle(type, payload);\n    }\n  }\n\n  parseStartup(body){\n    let i = 0; const p = {};\n    const read = () => { const s = i; while (i < body.length && body[i] !== 0) i++; const v = body.slice(s, i).toString(); i++; return v; };\n    while (i < body.length - 1) { const k = read(); if (!k) break; p[k] = read(); }\n    if (p.database) this.tenant = p.database;\n  }\n\n  sendStartupReply(){\n    this.send(Buffer.from([0x52,0,0,0,8,0,0,0,0])); // AuthOk\n    const param = (k,v) => { const kb=Buffer.from(k+'\\0'), vb=Buffer.from(v+'\\0'); const m=Buffer.alloc(5+kb.length+vb.length); m.writeUInt8(0x53,0); m.writeInt32BE(m.length-1,1); kb.copy(m,5); vb.copy(m,5+kb.length); this.send(m); };\n    param('server_version','15.0'); param('server_encoding','UTF8'); param('client_encoding','UTF8');\n    param('DateStyle','ISO, MDY'); param('TimeZone','UTC'); param('is_superuser','on');\n    const k = Buffer.alloc(13); k.writeUInt8(0x4B,0); k.writeInt32BE(12,1); k.writeInt32BE(1,5); k.writeInt32BE(1,9); this.send(k);\n    this.send(Buffer.from([0x5A,0,0,0,5,0x49])); // ReadyForQuery\n  }\n\n  async handle(type, payload){\n    if (type === 0x51) { // Simple Query\n      const sql = payload.slice(0, payload.length-1).toString('utf8').trim();\n      try {\n        const ast = parseSQL(sql);\n        const plan = planQuery(ast);\n        const exec = new Executor(this.smgr, this.tenant);\n        const res = await exec.execute(plan);\n        if (res.columns && res.columns.length) {\n          // RowDescription\n          const p=[]; const c=Buffer.alloc(2); c.writeInt16BE(res.columns.length,0); p.push(c);\n          res.columns.forEach(col=>{ p.push(Buffer.from(col.name+'\\0')); const m=Buffer.alloc(18); m.writeInt32BE(25,6); p.push(m); });\n          const pl=Buffer.concat(p); const h=Buffer.alloc(5); h.writeUInt8(0x54,0); h.writeInt32BE(4+pl.length,1); this.send(Buffer.concat([h,pl]));\n          // DataRows\n          (res.rows||[]).forEach(r=>{ const p2=[]; const c2=Buffer.alloc(2); c2.writeInt16BE(res.columns.length,0); p2.push(c2);\n            res.columns.forEach(col=>{ const v=r[col.name]; const vb=Buffer.from(String(v??'')); const lb=Buffer.alloc(4); lb.writeInt32BE(vb.length,0); p2.push(lb); p2.push(vb); });\n            const pl2=Buffer.concat(p2); const h2=Buffer.alloc(5); h2.writeUInt8(0x44,0); h2.writeInt32BE(4+pl2.length,1); this.send(Buffer.concat([h2,pl2])); });\n        }\n        const tag = res.command==='SELECT' ? `SELECT ${res.rowCount}` : res.command;\n        const tb=Buffer.from(tag+'\\0'); const b=Buffer.alloc(5+tb.length); b.writeUInt8(0x43,0); b.writeInt32BE(4+tb.length,1); tb.copy(b,5); this.send(b);\n      } catch(e){\n        const f=[Buffer.from('SERROR\\0'),Buffer.from('C42000\\0'),Buffer.from('M'+e.message+'\\0'),Buffer.from('\\0')];\n        const pl=Buffer.concat(f); const h=Buffer.alloc(5); h.writeUInt8(0x45,0); h.writeInt32BE(4+pl.length,1); this.send(Buffer.concat([h,pl]));\n      }\n      this.send(Buffer.from([0x5A,0,0,0,5,0x49]));\n    } else if (type === 0x58) { /* terminate */ }\n    else { this.send(Buffer.from([0x5A,0,0,0,5,0x49])); }\n  }\n}\n","src/tenant/provision.js":"import { defaultManifest, saveManifest } from '../storage/manifest.js';\nimport { randomToken } from '../core/utils.js';\nimport { DRIME_BASE, GATEWAY_HOST, GATEWAY_PORT } from '../core/constants.js';\nexport async function provisionDatabase(apiKey, tenantId, dbName, smgr = null, keyId = null) {\n  if (!smgr) { const { DrimeSmgr } = await import('../storage/drime_smgr.js'); smgr = new DrimeSmgr(apiKey, DRIME_BASE); }\n  const manifest = defaultManifest(tenantId, dbName);\n  if (keyId) manifest.keyId = keyId;\n  await saveManifest(smgr, tenantId, manifest, 0);\n  const token = randomToken();\n  const dsn = `postgresql://${dbName}:${token}@${GATEWAY_HOST}:${GATEWAY_PORT}/${dbName}?sslmode=require`;\n  return { tenantId, dbName, token, dsn };\n}\n","src/core/constants.js":"export const DRIME_BASE = 'https://app.drime.cloud/api/v1';\nexport const GATEWAY_HOST = 'gate.ne7sql.dev'; // Your future Wire Gateway domain\nexport const GATEWAY_PORT = 5432;\n","wrangler.toml":"name = \"ne7-sql-worker\"\nmain = \"src/index.js\"\ncompatibility_date = \"2024-09-23\"\ncompatibility_flags = [\"nodejs_compat\"]\n\nkv_namespaces = [\n  { binding = \"NE7_KV\", id = \"3ed942f890814320a86055f407af5ef3\" }\n]\n"};
